// Con try/catch
fun leerNumero(): Int {
    while (true) {
        try {
            return readln().toInt()
        } catch (e: NumberFormatException) {
            println("No es un número, intenta de nuevo")
        }
    }
}

// Con toIntOrNull (más idiomática)
fun leerNumero2(): Int {
    while (true) {
        readln().toIntOrNull()?.let { return it }
        println("No es un número, intenta de nuevo")
    }
}

fun main() = println(leerNumero2() * 2)

