class Pila<T> {
    private val elementos = mutableListOf<T>()
    fun push(e: T) = elementos.add(e)
    fun pop(): T? = elementos.removeLastOrNull()
    fun peek(): T? = elementos.lastOrNull()
    fun isEmpty() = elementos.isEmpty()
}

