sealed class Respuesta<out T> {
    data class Exito<T>(val dato: T) : Respuesta<T>()
    data class Error(val mensaje: String) : Respuesta<Nothing>()
}

fun buscarUsuario(id: Int): Respuesta<String> =
    if (id == 1) Respuesta.Exito("Ana") else Respuesta.Error("No encontrado")

fun main() {
    when (val r = buscarUsuario(2)) {
        is Respuesta.Exito -> println(r.dato)
        is Respuesta.Error -> println(r.mensaje)
    }
}

