import kotlinx.coroutines.*
import kotlin.system.measureTimeMillis

suspend fun descargar(id: Int): String {
    delay((500L..1500L).random())
    return "Archivo $id"
}

fun main() = runBlocking {
    val secuencial = measureTimeMillis {
        for (i in 1..5) descargar(i)
    }
    val paralelo = measureTimeMillis {
        (1..5).map { async { descargar(it) } }.awaitAll()
    }
    println("Secuencial: $secuencial ms, paralelo: $paralelo ms")
}

